export const W=900,H=1200;
export function stroke(ctx,s){const p=s.points;if(!p.length)return;ctx.save();ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.globalAlpha=s.tool==='highlighter'?.3:1;ctx.lineCap='round';ctx.lineJoin='round';if(s.tool==='highlighter'){ctx.lineWidth=s.width*5;ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);for(const q of p.slice(1))ctx.lineTo(q[0],q[1]);if(p.length===1)ctx.lineTo(p[0][0]+.1,p[0][1]);ctx.stroke();}else{for(let i=0;i<p.length;i++){const a=p[Math.max(0,i-1)],b=p[i];ctx.lineWidth=s.width*(.35+.9*((a[2]+b[2])/2));ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke();if(i===0){ctx.beginPath();ctx.arc(b[0],b[1],ctx.lineWidth/2,0,Math.PI*2);ctx.fill();}}}ctx.restore();}
export function renderInk(canvas,strokes){const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);c.save();c.scale(canvas.width/W,canvas.height/H);for(const s of strokes)stroke(c,s);c.restore();}
export function paper(ctx,template){ctx.fillStyle='#101113';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#242527';ctx.fillStyle='#343435';ctx.lineWidth=.6;if(template==='dots'){for(let y=32;y<H;y+=28)for(let x=32;x<W;x+=28){ctx.beginPath();ctx.arc(x,y,.8,0,Math.PI*2);ctx.fill();}}else if(template==='grid'||template==='ruled'){for(let y=32;y<H;y+=28){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}if(template==='grid')for(let x=32;x<W;x+=28){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}}}
export function pageImage(p){const c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');paper(x,p.template);x.fillStyle='#eee8db';x.font='24px Georgia';let y=100;for(const line of p.text.split('\n')){let current='';for(const word of line.split(' ')){if(x.measureText(current+word).width>744){x.fillText(current,78,y);y+=38;current='';}current+=word+' ';}x.fillText(current,78,y);y+=38;}for(const s of p.strokes)stroke(x,s);return c;}
export function hitStroke(s,x,y,radius=16){return s.points.some((b,i)=>{const a=s.points[Math.max(0,i-1)],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy||1)));return Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy)<radius+(s.tool==='highlighter'?s.width*2.5:s.width);});}
export class InkSurface{
 constructor(canvas,options){this.canvas=canvas;this.options=options;this.active=null;this.frame=0;this.pan=null;this.baseDirty=true;this.cache=null;this.down=e=>this.start(e);this.move=e=>this.update(e);this.up=e=>this.end(e);canvas.addEventListener('pointerdown',this.down);canvas.addEventListener('pointermove',this.move);canvas.addEventListener('pointerup',this.up);canvas.addEventListener('pointercancel',this.up);canvas.addEventListener('lostpointercapture',this.up);}
 point(e){const r=this.canvas.getBoundingClientRect();return [Math.max(0,Math.min(W,(e.clientX-r.left)*W/r.width)),Math.max(0,Math.min(H,(e.clientY-r.top)*H/r.height)),e.pointerType==='pen'?Math.max(.05,e.pressure):.5];}
 start(e){const o=this.options;if(this.active)return;if(e.pointerType==='touch'&&o.pencilOnly()){this.pan={id:e.pointerId,x:e.clientX,y:e.clientY};this.canvas.setPointerCapture(e.pointerId);return;}if(e.button!==0||o.tool()==='text')return;e.preventDefault();this.pan=null;this.canvas.setPointerCapture(e.pointerId);o.before();const [x,y]=this.point(e);this.active={id:e.pointerId,tool:o.tool(),color:o.color(),width:o.width(),points:[this.point(e)]};if(this.active.tool==='eraser')o.erase(x,y);this.draw();}
 update(e){if(this.active?.id===e.pointerId){e.preventDefault();for(const ev of (e.getCoalescedEvents?.().length?e.getCoalescedEvents():[e])){const p=this.point(ev);if(this.active.tool==='eraser')this.options.erase(p[0],p[1]);else this.active.points.push(p);}this.draw(this.active.tool==='eraser');}else if(this.pan?.id===e.pointerId){const host=this.canvas.closest('.paper-scroll');host.scrollTop+=this.pan.y-e.clientY;host.scrollLeft+=this.pan.x-e.clientX;this.pan.x=e.clientX;this.pan.y=e.clientY;}}
 end(e){if(this.pan?.id===e.pointerId)this.pan=null;if(this.active?.id!==e.pointerId)return;const s=this.active;this.active=null;if(s.tool!=='eraser'){delete s.id;this.options.commit(s);}else this.options.commit(null);this.draw();}
 draw(baseChanged=true){this.baseDirty=this.baseDirty||baseChanged;if(this.frame)return;this.frame=requestAnimationFrame(()=>{this.frame=0;if(!this.cache){this.cache=document.createElement('canvas');this.cache.width=this.canvas.width;this.cache.height=this.canvas.height;}if(this.baseDirty){renderInk(this.cache,this.options.strokes());this.baseDirty=false;}const c=this.canvas.getContext('2d');c.clearRect(0,0,this.canvas.width,this.canvas.height);c.drawImage(this.cache,0,0);if(this.active&&this.active.tool!=='eraser'){c.save();c.scale(this.canvas.width/W,this.canvas.height/H);stroke(c,this.active);c.restore();}});}
 destroy(){cancelAnimationFrame(this.frame);for(const [n,f]of [['pointerdown',this.down],['pointermove',this.move],['pointerup',this.up],['pointercancel',this.up],['lostpointercapture',this.up]])this.canvas.removeEventListener(n,f);}
}
